import { SpriteRenderer } from '../js/sprite.js';
import { loadArtImages } from '../js/art.js';
import type { ArtDescriptor } from '../../shared/art';

async function boot() {
  const response = await fetch('art://pack/manifest.json');
  if (!response.ok) throw new Error('Art pack unavailable');
  // Descriptor is generated by the trusted main-process manifest boundary.
  const pack: ArtDescriptor = await response.json();
  console.debug('ART_PREVIEW:descriptor-loaded');
  const art = await loadArtImages(pack, (url: string) => new Promise<HTMLImageElement>((resolve, reject) => {
    const image = new Image();
    image.crossOrigin = 'anonymous';
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error('Image unavailable'));
    image.src = url;
  }));
  console.debug('ART_PREVIEW:image-loaded');
  const canvas = document.querySelector<HTMLCanvasElement>('#sprite')!;
  const sprite = new SpriteRenderer(canvas, art.image);
  console.debug('ART_PREVIEW:shader-ready');
  sprite.resize(0.8);
  sprite.draw({ seed: 0, boil: 0, hair: 0, head: 0, mane: 0, armL: 0, armR: 0, longL: 1, longR: 1,
    sit: 0, bend: 0, kickL: 0, kickR: 0, smear: [0, 0], echo: [0, 0], glitch: 0, glitchSeed: 0,
    split: 0, collapse: 0, dissolve: 0, sparkle: 0, grade: 0, sil: [0, 0, 0], silAmount: 0,
    misreg: [0, 0], alpha: 1 });
  const gl = sprite.gl;
  const pixels = new Uint8Array(canvas.width * canvas.height * 4);
  gl.readPixels(0, 0, canvas.width, canvas.height, gl.RGBA, gl.UNSIGNED_BYTE, pixels);
  const rendered = pixels.some((value: number, index: number) => index % 4 === 3 && value > 0);
  if (!rendered) throw new Error('Sprite renderer produced no visible pixels');
  document.querySelector('h1')!.textContent = pack.name;
  document.querySelector('#source')!.textContent = `${pack.source} art pack · mochi-v1`;
  document.querySelector('#status')!.textContent = 'Sprite ready. Optional assets are used when available.';
  document.body.dataset.source = pack.source;
  document.body.dataset.optional = `${Object.keys(art.faces).length}-${Object.keys(art.cutins).length}-${art.intro ? Object.keys(art.intro).length : 0}`;
  document.body.dataset.ready = 'true';
  window.dispatchEvent(new Event('art-ready'));
}
boot().catch((error: unknown) => {
  console.error('Art preview failed:', error instanceof Error ? error.message : 'Unknown error');
  document.querySelector('#status')!.textContent = 'Art could not be displayed. Check the pack and graphics support.';
  document.body.dataset.ready = 'failed';
});
